compile.workshop:
variables {
    global:
        0: g
}

rule ("player set lengths") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Global Variable(g, Number Of Living Players(Team 1));
        Set Global Variable(g, Number Of Dead Players(Team 1));
        Set Global Variable(g, Number Of Players(Team 1));
        Set Global Variable(g, Number Of Players On Objective(Team 1));
        Set Global Variable(g, Number Of Heroes(Hero(Ana), Team 1));
        Set Global Variable(g, Number Of Players(All Teams));
        Set Global Variable(g, Count Of(All Players Not On Objective(Team 1)));
        Set Global Variable(g, Count Of(Global.g));
    }
}

//Optimize for size enabled
rule ("player set lengths sized") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Global Variable(g, Number Of Living Players(Team 1));
        Set Global Variable(g, Number Of Heroes(Hero(Ana), Team 1));
    }
}

//Optimizations disabled
rule ("player set lengths unoptimized") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Global Variable(g, Count Of(All Living Players(Team 1)));
        Set Global Variable(g, Count Of(Players On Hero(Hero(Ana), Team 1)));
        Set Global Variable(g, Count Of(Global.g));
    }
}

